function DocumentReview({row,open,onClose,onSave}:{row:Row;open:boolean;onClose:()=>void;onSave:(documents:Enrollment['documents'])=>Promise<void>}){
  const [documents,setDocuments]=useState(row.enrollment.documents);
  const [saving,setSaving]=useState(false);
  const [error,setError]=useState('');
  const update=(index:number,change:Partial<Enrollment['documents'][number]>)=>
    setDocuments(current=>current.map((document,i)=>i===index?{...document,...change}:document));
  const save=async()=>{
    setSaving(true);setError('');
    try{await onSave(documents)}
    catch(err){setError((err as Error).message);setSaving(false)}
  };
  return <Modal title="Control documental" subtitle={`${fullName(row.student)} · Curso lectivo ${row.enrollment.year}`} onClose={onClose}>
    <div className="modal-body">
      {!documents.length&&<Empty title="Sin requisitos documentales registrados" text="Este registro todavía no tiene requisitos documentales."/>}
      <div className="document-edit">{documents.map((document,i)=><div className="form-subcard" key={document.name}>
        <div className="flex between"><strong><FileText size={16}/>{document.name}</strong>
          <select aria-label={`Estado de ${document.name}`} value={document.status} disabled={!open||saving}
            onChange={event=>update(i,{status:event.target.value as DocStatus,date:new Date().toISOString()})}>
            {['Pendiente','Recibido','Verificado','Rechazado','No aplica'].map(status=><option key={status}>{status}</option>)}
          </select>
        </div>
        <input aria-label={`Observaciones de ${document.name}`} value={document.note} placeholder="Observaciones del requisito"
          readOnly={!open||saving} onChange={event=>update(i,{note:event.target.value})}/>
      </div>)}</div>
      {error&&<div className="error-banner" role="alert">{error}</div>}
    </div>
    <div className="modal-footer">
      <button className="button secondary" onClick={onClose}>Cerrar</button>
      {open&&<button className="button primary" disabled={saving||!documents.length} onClick={()=>void save()}><Save size={16}/>Guardar revisión</button>}
    </div>
  </Modal>;
}
function EnrollmentSummary({student:s,enrollment:e,manual}:{student:Student;enrollment:Enrollment;manual:boolean}){
  const sections:[string,[string,string|undefined][]][]=[
    ['Identificación y datos personales',[
      ['Nombre completo',fullName(s)],['Tipo de identificación',s.idType],['Identificación',s.identification],
      ['Fecha de nacimiento',formatDate(s.birthdate)],['Género',s.gender],['Teléfono del estudiante',s.phone||'Sin registrar (opcional)'],['Fotografía',s.photo?'Adjunta':'Sin adjuntar'],
    ]],
    ['Ubicación académica y domicilio',[
      ['Curso lectivo',String(e.year)],['Nivel',`${e.grade}°`],['Sección',e.section?sectionLabel(e):'Sin asignar'],
      ['Subgrupo',e.subgroup||'No aplica'],['Especialidad',e.specialty||'No aplica'],['Condición académica',e.condition],
      ['Estado',manual?'Activo':e.status],...(e.effectiveDate?[['Fecha efectiva',formatDate(e.effectiveDate)] as [string,string]]:[]),
      ['Centro educativo de procedencia',s.previousSchool],['Provincia',s.province],['Cantón',s.canton],
      ['Distrito',s.district],['Dirección exacta',s.address],
    ]],
    ['Póliza, educación y autorizaciones',[
      ['Número de póliza',e.policy],['Vencimiento',formatDate(e.policyExpiry)],['Adecuación',e.accommodation],
      ['Educación Religiosa',e.religion?'Sí':'No'],['Autorización de fotografías',e.photoConsent],
    ]],
    ['Información médica y observaciones',[
      ['Información médica',e.medical.state],['Condiciones médicas',e.medical.conditions],['Alergias',e.medical.allergies],
      ['Medicamentos autorizados',e.medical.medications],['Medicamentos contraindicados',e.medical.contraindications],
      ['Documentación de emergencias / DEA',e.medical.emergency],['Observaciones administrativas',e.notes],
    ]],
  ];
  return <div className="enrollment-summary">
    {sections.map(([title,details])=><section className="review-box" key={title}><h4>{title}</h4><dl className="detail-grid">{details.map(([key,value])=><Detail key={key} title={key} value={value}/>)}</dl></section>)}
    {([[s.guardians,'Personas encargadas'],[s.departureContacts,'Personas autorizadas para salida']] as const).map(([contacts,title])=><section className="review-box" key={title}>
      <h4>{title}</h4>
      {contacts.length?contacts.map(g=><dl className="detail-grid" key={g.id}><Detail title="Nombre" value={g.name}/><Detail title="Identificación" value={g.identification}/><Detail title="Teléfono" value={g.phone}/><Detail title="Correo" value={g.email}/><Detail title="Parentesco" value={g.relationship}/><Detail title="Contacto principal" value={g.primary?'Sí':'No'}/><Detail title="Autorización de salida" value={g.departure?'Sí':'No'}/></dl>):<p>Sin registrar</p>}
    </section>)}
  </div>;
}

function Verification({row,db,onClose,onEdit,onDocuments,onSave}:{row:Row;db:State;onClose:()=>void;onEdit:()=>void;onDocuments:()=>void;onSave:(verified:string[],activate:boolean)=>Promise<void>}){const [verified,setVerified]=useState([...row.enrollment.verified]),[error,setError]=useState(''),[saving,setSaving]=useState(false);const testRow={...row,enrollment:{...row.enrollment,verified}},ready=readiness(testRow,db);return <Modal wide title="Verificar y confirmar matrícula" subtitle={`${fullName(row.student)} · ${groupLabel(row.enrollment)} · ${row.enrollment.year}`} onClose={onClose}><div className="modal-body"><div className="verification-progress"><span><strong>{verified.length} de 12</strong> verificaciones completas</span><strong>{Math.round(verified.length/12*100)}%</strong><div className="progress"><i style={{width:`${verified.length/12*100}%`}}/></div></div><p className="muted">Marque cada apartado después de contrastarlo con el expediente y la persona encargada.</p><div className="verification-grid">{verificationSteps.map((v,i)=><label key={v} className={verified.includes(v)?'verified':''}><span>{verified.includes(v)?<Check size={16}/>:String(i+1).padStart(2,'0')}</span><strong>{v}</strong><input type="checkbox" checked={verified.includes(v)} onChange={e=>setVerified(e.target.checked?[...verified,v]:verified.filter(x=>x!==v))}/></label>)}</div>{ready.errors.length>0&&<div className="validation-box"><h4><TriangleAlert size={17}/>Información pendiente</h4><ul>{ready.errors.map(v=><li key={v}>{v}</li>)}</ul><button className="text-button" onClick={onEdit}>Abrir el expediente y completar datos<ArrowRight size={15}/></button>{row.enrollment.documents.some(d=>!['Verificado','No aplica'].includes(d.status))&&<button className="text-button" onClick={onDocuments}>Ir a Control documental<ArrowRight size={16}/></button>}</div>}{ready.warnings.length>0&&<div className="warning-box">{ready.warnings.map(w=><p key={w}><TriangleAlert size={16}/>{w}</p>)}</div>}{ready.ready&&<div className="success-banner"><CheckCircle2 size={19}/>El expediente está listo para confirmar la matrícula.</div>}{error&&<div className="error-banner">{error}</div>}</div><div className="modal-footer"><button className="button secondary" disabled={saving} onClick={async()=>{setSaving(true);try{await onSave(verified,false)}catch(e){setError((e as Error).message)}finally{setSaving(false)}}}><Save size={16}/>Guardar progreso</button><button className="button primary" disabled={!ready.ready||saving} onClick={async()=>{setSaving(true);try{await onSave(verified,true)}catch(e){setError((e as Error).message)}finally{setSaving(false)}}}><CheckCheck size={17}/>Confirmar matrícula y activar estudiante</button></div></Modal>}
function Importer({db,year,onClose,onImport}:{db:State;year:number;onClose:()=>void;onImport:(list:Row[])=>Promise<void>}){const [fileName,setFileName]=useState(''),[raw,setRaw]=useState<Record<string,unknown>[]>([]),[mapping,setMapping]=useState<Record<string,string>>({}),[entries,setEntries]=useState<ImportEntry[]>([]),[step,setStep]=useState(0),[error,setError]=useState(''),[busy,setBusy]=useState(false);const fields=studentImportFields;const handleFile=async(file?:File)=>{if(!file)return;setError('');if(file.size>5*1024*1024||!(/\.(xlsx|csv)$/i.test(file.name))){setError('Seleccione un archivo XLSX o CSV de hasta 5 MB.');return}try{const data=await readSheet(file);if(!data.length)throw Error('El archivo no contiene estudiantes.');if(data.length>3000)throw Error('El máximo por importación es de 3000 filas.');setRaw(data);setFileName(file.name);const headers=Object.keys(data[0]);setMapping(Object.fromEntries(fields.map(([k])=>[k,headers.find(h=>normalize(h).replace(/\s/g,'_')===k)||''])));setStep(1)}catch(e){setError(`No se pudo leer el archivo. ${(e as Error).message}`)}};
const preview=()=>{if(['identificacion','nombre','primer_apellido'].some(k=>!mapping[k])){setError('Asigne las tres columnas obligatorias.');return}const result=studentImportPreview(raw,mapping,db,year);setEntries(result);setError('');setStep(2)};
const valid=entries.filter(e=>!e.errors.length);return <Modal wide title="Importar estudiantes" subtitle={`Curso lectivo ${year} · Las matrículas ingresan como inactivas.`} onClose={onClose}><div className="import-steps">{['Seleccionar archivo','Asignar columnas','Validar y confirmar'].map((v,i)=><div className={i===step?'active':''} key={v}><span>{i+1}</span>{v}</div>)}</div><div className="modal-body">{error&&<div className="error-banner" role="alert">{error}</div>}{step===0&&<><label className="drop-zone"><span className="icon-tile teal"><Upload size={28}/></span><h3>Su base de datos, en un solo paso.</h3><p>Seleccione un archivo de Excel (.xlsx) o CSV.</p><span className="button primary">Seleccionar archivo</span><small>Máximo 5 MB · 3000 registros por importación</small><input type="file" accept=".xlsx,.csv" onChange={e=>handleFile(e.target.files?.[0])}/></label><button className="template-download" onClick={template}><FileText size={22}/><span><strong>¿Primera importación?</strong><small>Descargue la plantilla con las columnas correctas.</small></span><Download size={19}/></button></>}{step===1&&<><div className="info-banner"><FileText size={20}/><span><strong>{fileName}</strong> · {raw.length} filas detectadas</span></div><p>Relacione las columnas del archivo con los datos del estudiante.</p><div className="form-grid">{fields.map(([key,label])=><Field key={key} label={label}><select value={mapping[key]||''} onChange={e=>setMapping({...mapping,[key]:e.target.value})}><option value="">No importar este campo</option>{Object.keys(raw[0]||{}).map(k=><option key={k}>{k}</option>)}</select></Field>)}</div></>}{step===2&&<><div className="import-summary"><Badge tone="green">{valid.length} listos para importar</Badge><Badge tone="red">{entries.length-valid.length} con errores</Badge><Badge tone="amber">Todos ingresarán inactivos</Badge></div><div className="table-wrap import-preview"><table><thead><tr><th>FILA</th><th>IDENTIFICACIÓN</th><th>NOMBRE</th><th>VALIDACIÓN</th></tr></thead><tbody>{entries.map(x=><tr key={x.line}><td>{x.line}</td><td>{x.row.student.identification}</td><td>{fullName(x.row.student)}</td><td>{x.errors.length?<span className="red-text">{x.errors.join(' ')}</span>:<Badge tone="green">Listo</Badge>}</td></tr>)}</tbody></table></div>{entries.length!==valid.length&&<p className="muted">Solo se importarán las filas válidas. Las filas con errores quedan excluidas para que pueda corregirlas.</p>}</>}</div><div className="modal-footer"><button className="button secondary" onClick={step?()=>setStep(step-1):onClose}>{step?'Anterior':'Cancelar'}</button>{step===1&&<button className="button primary" onClick={preview}>Validar registros<ArrowRight size={16}/></button>}{step===2&&<button className="button primary" disabled={!valid.length||busy} onClick={async()=>{setBusy(true);try{await onImport(valid.map(v=>v.row))}catch(e){setError((e as Error).message)}finally{setBusy(false)}}}><Check size={17}/>Confirmar importación de {valid.length} estudiantes</button>}</div></Modal>}
type Mutation=(fn:(s:State)=>void,message?:string)=>Promise<void>;
type Ask=(v:{title:string;body:string;action:()=>Promise<void>})=>void;
function Years({db,mutate,current,setYear,ask}:{db:State;mutate:Mutation;current:number;setYear:(n:number)=>void;ask:Ask}){
  const [newYear,setNewYear]=useState(Math.max(2026,...db.years.map(y=>y.year))+1);
  const [error,setError]=useState('');
  const [busy,setBusy]=useState(false);
  const create=async()=>{
    setError('');setBusy(true);
    try{
      if(newYear<2020||newYear>2100||db.years.some(y=>y.year===newYear))throw Error('Ingrese un curso válido que todavía no exista.');
      await mutate(state=>{
        state.years.push({year:newYear,status:'Abierto'});
        for(const grade of [7,8,9,10,11,12])for(const section of ['1','2','3','4'])for(const subgroup of ['A','B']){
          state.groups.push({id:uid(),year:newYear,grade,section,subgroup,specialty:'',capacity:17});
        }
        audit(state,'Curso lectivo creado',String(newYear));
      },'Curso creado. Configure las especialidades antes de matricular en Diversificada.');
      setYear(newYear);setNewYear(newYear+1);
    }catch(err){setError((err as Error).message)}
    finally{setBusy(false)}
  };
  return <>
    <section className="card"><div className="card-heading"><div><h3>Cursos lectivos</h3><p>Cada curso conserva sus matrículas y su historial.</p></div></div>
      <div className="year-cards">{db.years.map(y=><div className="year-card" key={y.year}><h2>{y.year}</h2><p>{y.status} · {rows(db,y.year).length} expedientes</p>
        <button className="button secondary" onClick={()=>setYear(y.year)}>{current===y.year?'Curso seleccionado':'Consultar'}</button>
        <button className="text-button" onClick={()=>ask({title:y.status==='Abierto'?'Cerrar curso lectivo':'Abrir curso lectivo',body:'El historial y los expedientes se conservarán.',
          action:()=>mutate(state=>{const target=state.years.find(v=>v.year===y.year)!;target.status=target.status==='Abierto'?'Cerrado':'Abierto'},'Curso actualizado.')})}>
          {y.status==='Abierto'?'Cerrar curso':'Abrir curso'}</button>
      </div>)}</div>
      {!db.years.length&&<div className="modal-body"><p>Cree el primer curso para comenzar la configuración académica.</p></div>}
    </section>
    <section className="card"><div className="card-heading"><div><h3>Crear curso lectivo</h3><p>Se crearán secciones de 7° a 12° con subgrupos A y B y cupo de 17 por grupo. Asigne las especialidades de Diversificada en Organización académica.</p></div></div>
      <div className="modal-body"><label className="field"><span>Curso lectivo</span><input type="number" min={2020} max={2100} value={newYear} onChange={e=>setNewYear(Number(e.target.value))}/></label>
        {error&&<p role="alert" className="error-banner">{error}</p>}
        <button className="button primary" disabled={busy} onClick={()=>void create()}>{busy?'Creando…':'Crear curso vacío'}</button>
      </div>
    </section>
  </>;
}

function GroupEditor({group,db,onClose,onSave}:{group:Group;db:State;onClose:()=>void;onSave:(g:Group)=>Promise<void>}){const [g,setG]=useState({...group}),[err,setErr]=useState('');return <Modal title="Configurar grupo" subtitle={`Curso lectivo ${group.year}`} onClose={onClose}><div className="modal-body"><div className="form-grid"><Field label="Nivel"><select value={g.grade} onChange={e=>setG({...g,grade:+e.target.value,subgroup:'A',specialty:''})}>{[7,8,9,10,11,12].map(n=><option key={n} value={n}>{n}°</option>)}</select></Field><Field label="Sección"><select value={g.section} onChange={e=>setG({...g,section:e.target.value})}>{[1,2,3,4].map(n=><option key={n}>{n}</option>)}</select></Field>{<Field label="Subgrupo"><select value={g.subgroup} onChange={e=>setG({...g,subgroup:e.target.value})}>{['A','B','C','D'].map(v=><option key={v}>{v}</option>)}</select></Field>}{g.grade>=10&&<Field label="Especialidad"><select value={g.specialty} onChange={e=>setG({...g,specialty:e.target.value})}><option value="">Seleccione</option>{db.settings.specialties.map(v=><option key={v}>{v}</option>)}</select></Field>}<p className="muted">Cada sección admite hasta {SECTION_CAPACITY} estudiantes activos y cada subgrupo o especialidad hasta {GROUP_CAPACITY}.</p></div>{err&&<div className="error-banner">{err}</div>}</div><div className="modal-footer"><button className="button secondary" onClick={onClose}>Cancelar</button><button className="button primary" onClick={async()=>{try{if(g.grade>=10&&!g.specialty)throw Error('Seleccione la especialidad.');await onSave(g)}catch(e){setErr((e as Error).message)}}}><Save size={16}/>Guardar grupo</button></div></Modal>}
const reportTypes=[{name:'Listado de estudiantes',icon:Users,description:'Matrícula, secciones y datos generales.',columns:['name','identification','group']},{name:'Adecuaciones educativas',icon:BookOpen,description:'Estudiantes con ACNS y ACS.',columns:['name','identification','group','accommodation']},{name:'Pólizas estudiantiles',icon:ShieldCheck,description:'Cobertura, vencimiento y vigencia.',columns:['name','group','policy','expiry','insurance']},{name:'Personas autorizadas para salida',icon:UserRound,description:'Contactos autorizados por estudiante.',columns:['name','group','departure']},{name:'Encargados legales',icon:Phone,description:'Directorio de contactos principales.',columns:['name','group','guardian','phone']},{name:'Listas de firma',icon:ClipboardCheck,description:'Control de asistencia y firmas.',columns:['name','identification','group','signature']},{name:'Estudiantes aplazados',icon:Clock,description:'Seguimiento de condición académica.',columns:['name','group','condition','guardian','phone']},{name:'Retiros de matrícula',icon:LogOut,description:'Movimientos de retiro registrados.',columns:['name','identification','group']},{name:'Control documental',icon:FileText,description:'Estado de requisitos por estudiante.',columns:['name','group','documents']},{name:'Educación Religiosa',icon:BookOpen,description:'Participación por grupo y nivel.',columns:['name','group','religion']},{name:'Convocatoria',icon:CalendarDays,description:'Estudiantes en condición de convocatoria.',columns:['name','group','condition']},{name:'Informe personalizado',icon:SlidersHorizontal,description:'Elija las columnas de su informe.',columns:['name','identification','group']},{name:'Lista personalizada de estudiantes',icon:ClipboardCheck,description:'Configure el motivo, la fecha y el grupo para una lista de firmas.',columns:['number','identification','name','signature']},{name:originTitle,icon:BookOpen,description:'Estudiantes activos de sétimo y su escuela de procedencia.',columns:originColumns},{name:transferTitle,icon:LogOut,description:'Historial de traslados por fecha y nivel.',columns:[]}];
type ReportExport = (pdf:boolean,records:Row[],columns:string[],title:string,options:ReportOptions,askOrganization:boolean)=>Promise<void>;
const purposeOptions=['Reunión de padres de familia','Control de asistencia','Entrega de documentos','Actividad institucional','Convocatoria de estudiantes','Otro'];

function Reports({db,year,setYear,records,onExport,mutate,onPreview,toast}:{db:State;year:number;setYear:(year:number)=>void;records:Row[];onExport:ReportExport;mutate:Mutation;onPreview:(request:PdfPreviewRequest)=>void;toast:(message:string)=>void}){
  const [type,setType]=useState(0),[grade,setGrade]=useState(''),[section,setSection]=useState('');
  const [audience,setAudience]=useState(''),[scope,setScope]=useState('Activo'),[columns,setColumns]=useState(reportTypes[0].columns);
  const [landscape,setLandscape]=useState(false),[from,setFrom]=useState(''),[to,setTo]=useState(''),[name,setName]=useState('');
  const [purpose,setPurpose]=useState(''),[customPurpose,setCustomPurpose]=useState(''),[eventDate,setEventDate]=useState('');
  const [error,setError]=useState('');
  const report=reportTypes[type], purposeList=type===12;
  const groupOptions=db.groups.filter(g=>g.year===year&&(!grade||g.grade===+grade));
  const sectionOptions=[...new Map(groupOptions.map(g=>[sectionLabel(g),g])).values()].sort((a,b)=>sectionLabel(a).localeCompare(sectionLabel(b),'es',{numeric:true}));
  const groupsForSection=sectionOptions.find(g=>sectionLabel(g)===section);
  const audienceGroups=groupsForSection?db.groups.filter(g=>sectionKey(g)===sectionKey(groupsForSection)):[];
  const selectedGroup=audienceGroups.find(g=>g.id===audience);
  const filtered=records.filter(({enrollment:e})=>{
    if(grade&&e.grade!==+grade)return false;
    if(section&&(purposeList?sectionLabel(e):e.section)!==section)return false;
    if(selectedGroup && groupKey(e)!==groupKey(selectedGroup))return false;
    if(scope&&e.status!==scope)return false;
    if(type===1&&e.accommodation==='NP')return false;
    if(type===6&&e.condition!=='Aplazado')return false;
    if(type===7&&e.status!=='Retiro de matrícula')return false;
    if(type===9&&!e.religion)return false;
    if(type===10&&e.condition!=='Convocatoria')return false;
    return (!from||!!e.effectiveDate&&e.effectiveDate>=from)&&(!to||!!e.effectiveDate&&e.effectiveDate<=to);
  });
  const choose=(i:number)=>{
    setType(i);setColumns([...reportTypes[i].columns]);setScope(i===7?'Retiro de matrícula':'Activo');
    setFrom('');setTo('');setSection('');setAudience('');setError('');
  };
  const options:ReportOptions={
    section:purposeList?section:grade&&section?`${grade}-${section}`:'',
    purpose:purposeList?(purpose==='Otro'?customPurpose.trim():purpose):undefined,
    eventDate:purposeList?eventDate:undefined,
    audience:selectedGroup?groupTitle(selectedGroup):undefined,
    landscape,
    filters:[grade?`${grade}° nivel`:'Todos los niveles',!purposeList&&!grade&&section&&`Número de sección: ${section}`,scope||'Todos los estados',from&&`Desde ${formatDate(from)}`,to&&`Hasta ${formatDate(to)}`].filter(Boolean).join(' · '),
  };
  const layout=reportLayout(filtered,columns,'unified',options.section);
  const generate=async(pdf:boolean)=>{
    if(purposeList && (!options.purpose||!eventDate||!section)){
      setError('Complete el motivo, la fecha de la actividad y la sección antes de generar la lista.');
      return;
    }
    setError('');
    await onExport(pdf,filtered,columns,report.name,options,!selectedGroup);
  };
  return <>
    <div className="report-grid">{reportTypes.map((r,i)=><button className={`report-option ${type===i?'selected':''}`} key={r.name} onClick={()=>choose(i)}>
      <span className={`icon-tile ${type===i?'teal':'neutral'}`}><r.icon size={21}/></span><strong>{r.name}</strong><p>{r.description}</p>{type===i&&<CheckCircle2 size={17} className="report-selected"/>}
    </button>)}</div>
    {report.name===transferTitle?<TransferReport db={db} year={year} onPreview={onPreview} toast={toast}/>:report.name===originTitle?<OriginReport db={db} records={records} year={year} setYear={setYear} onExport={onExport}/>:
    <section className="card">
      <div className="card-heading"><div><h3>{report.name}</h3><p>Configure el alcance y revise el resultado antes de descargarlo.</p></div><Badge tone="teal">{filtered.length} estudiantes</Badge></div>
      <div className="report-config">
        <div className="form-grid three">
          {purposeList&&<>
            <Field label="Motivo de la lista"><select required value={purpose} onChange={e=>setPurpose(e.target.value)}><option value="">Seleccione un motivo</option>{purposeOptions.map(v=><option key={v}>{v}</option>)}</select></Field>
            {purpose==='Otro'&&<Field label="Escriba el motivo"><input required maxLength={160} value={customPurpose} onChange={e=>setCustomPurpose(e.target.value)}/></Field>}
            <Field label="Fecha de la actividad"><input required type="date" value={eventDate} onChange={e=>setEventDate(e.target.value)}/></Field>
          </>}
          <Field label="Nivel"><select value={grade} onChange={e=>{setGrade(e.target.value);setSection('');setAudience('')}}><option value="">Todos los niveles</option>{[7,8,9,10,11,12].map(g=><option key={g} value={g}>{g}° nivel</option>)}</select></Field>
          <Field label="Sección"><select required={purposeList} value={section} onChange={e=>{setSection(e.target.value);setAudience('')}}>
            <option value="">{purposeList?'Seleccione una sección':'Todas las secciones'}</option>
            {purposeList?sectionOptions.map(g=><option key={sectionKey(g)}>{sectionLabel(g)}</option>):[1,2,3,4].map(n=><option key={n}>{n}</option>)}
          </select></Field>
          {purposeList&&<Field label="Subgrupo o especialidad"><select value={audience} onChange={e=>setAudience(e.target.value)} disabled={!audienceGroups.length}>
            <option value="">Sección completa</option>{audienceGroups.map(g=><option key={g.id} value={g.id}>{groupTitle(g)}</option>)}
          </select></Field>}
          <Field label="Estado de matrícula"><select value={scope} onChange={e=>setScope(e.target.value)}><option value="">Todos los estados</option>{['Activo','Inactivo','Traslado','Retiro de matrícula'].map(v=><option key={v}>{v}</option>)}</select></Field>
          {type===7&&<><Field label="Retiro desde"><input type="date" value={from} onChange={e=>setFrom(e.target.value)}/></Field><Field label="Retiro hasta"><input type="date" value={to} onChange={e=>setTo(e.target.value)}/></Field></>}
        </div>
        {type===11&&<>
          <h4>Columnas del informe</h4>
          <div className="column-options">{Object.entries(reportColumns).filter(([k])=>k!=='group').map(([k,label])=><label key={k}><input type="checkbox" checked={columns.includes(k)} onChange={e=>setColumns(e.target.checked?[...columns,k]:columns.filter(v=>v!==k))}/>{label}</label>)}</div>
          <p className="muted">La columna Sección se ajusta según el alcance del informe.</p>
          <div className="flex template-config">
            <input placeholder="Nombre de la plantilla" aria-label="Nombre de la plantilla" value={name} onChange={e=>setName(e.target.value)}/>
            <button className="button secondary" disabled={!name.trim()||!columns.length} onClick={async()=>{await mutate(s=>{s.reportTemplates.push({name:name.trim(),columns:[...columns],report:report.name});audit(s,'Plantilla de informe guardada',name)},'Plantilla guardada.');setName('')}}><Save size={16}/>Guardar plantilla</button>
            {db.reportTemplates.length>0&&<select aria-label="Cargar plantilla" defaultValue="" onChange={e=>{const t=e.target.value&&db.reportTemplates[+e.target.value];if(t)setColumns(studentReportColumns(t.columns))}}><option value="">Cargar plantilla…</option>{db.reportTemplates.map((t,i)=><option key={i} value={i}>{t.name}</option>)}</select>}
          </div>
        </>}
        {error&&<p className="error-banner" role="alert">{error}</p>}
        <div className="report-export">
          <label><input type="checkbox" checked={landscape} onChange={e=>setLandscape(e.target.checked)}/>Orientación horizontal</label>
          <div className="flex">
            <button className="button secondary" disabled={!layout.columns.length} onClick={()=>void generate(false)}><Download size={16}/>Descargar Excel</button>
            <button className="button primary" disabled={!layout.columns.length} onClick={()=>void generate(true)}><Printer size={16}/>Generar PDF</button>
          </div>
        </div>
      </div>
      <div className="preview-label"><FileText size={15}/>VISTA PREVIA · Primeros 8 registros{layout.section?` · Sección ${layout.section}`:''}{selectedGroup?` · ${groupTitle(selectedGroup)}`:''}</div>
      <div className="table-wrap"><table>
        <thead><tr>{layout.columns.map(k=><th key={k}>{reportColumnLabel(k,options).toUpperCase()}</th>)}</tr></thead>
        <tbody>{layout.blocks[0].rows.slice(0,8).map((r,i)=><tr key={r.enrollment.id}>{layout.columns.map(k=><td key={k}>{k==='signature'?'':reportValue(r,k,i)||'—'}</td>)}</tr>)}</tbody>
      </table></div>
      {!filtered.length&&<Empty title="Sin estudiantes para este informe" text="Ajuste los filtros o elija otro listado."/>}
      <p className="report-footnote">Los informes utilizan el encabezado y pie configurados por la institución.</p>
    </section>}
  </>;
}
function SettingsPage({db,mutate}:{db:State;mutate:Mutation}){const [settings,setSettings]=useState(structuredClone(db.settings)),[specialty,setSpecialty]=useState(''),[doc,setDoc]=useState(''),[error,setError]=useState('');return <section className="card"><div className="card-heading"><div><h3>Identidad y preferencias de la institución</h3><p>Los cambios se guardan en la configuración institucional.</p></div></div><div className="modal-body"><div className="settings-brand"><img src={`${import.meta.env.BASE_URL}assets/escudo.jpeg`} alt="Escudo institucional"/><div><h3>CTP Cañas</h3><p>Ministerio de Educación Pública<br/>Dirección Regional de Educación Cañas</p></div></div><div className="form-grid"><Field label="Nombre de la institución" full><input value={settings.institution} onChange={e=>setSettings({...settings,institution:e.target.value})}/></Field><Field label="Teléfono"><input value={settings.phone} onChange={e=>setSettings({...settings,phone:e.target.value})}/></Field><Field label="Correo institucional"><input type="email" value={settings.email} onChange={e=>setSettings({...settings,email:e.target.value})}/></Field><Field label="Aviso de vencimiento de póliza (días)"><input type="number" min={1} max={90} value={settings.insuranceThreshold} onChange={e=>setSettings({...settings,insuranceThreshold:+e.target.value})}/></Field><Field label="Zona horaria"><input disabled value="America/Costa_Rica"/></Field></div><h3 className="form-section">Especialidades técnicas</h3><div className="tag-list">{settings.specialties.map(v=><span key={v}>{v}<button aria-label={`Quitar ${v}`} onClick={()=>{if(db.enrollments.some(e=>e.specialty===v)){setError('La especialidad tiene matrículas históricas y debe conservarse.');return}setSettings({...settings,specialties:settings.specialties.filter(s=>s!==v)})}}><X size={13}/></button></span>)}</div><div className="flex add-config"><input aria-label="Nueva especialidad" placeholder="Nombre de la especialidad" value={specialty} onChange={e=>setSpecialty(e.target.value)}/><button className="button secondary" disabled={!specialty.trim()} onClick={()=>{if(settings.specialties.some(v=>normalize(v)===normalize(specialty)))return;setSettings({...settings,specialties:[...settings.specialties,specialty.trim()]});setSpecialty('')}}><Plus size={16}/>Agregar</button></div><h3 className="form-section">Requisitos de matrícula</h3><p className="muted">Los nuevos requisitos se aplican a las matrículas que se registren a partir del cambio.</p><div className="tag-list">{settings.documents.map(v=><span key={v}>{v}<button aria-label={`Quitar requisito ${v}`} onClick={()=>setSettings({...settings,documents:settings.documents.filter(s=>s!==v)})}><X size={13}/></button></span>)}</div><div className="flex add-config"><input aria-label="Nuevo requisito" placeholder="Nombre del documento requerido" value={doc} onChange={e=>setDoc(e.target.value)}/><button className="button secondary" disabled={!doc.trim()} onClick={()=>{if(settings.documents.includes(doc.trim()))return;setSettings({...settings,documents:[...settings.documents,doc.trim()]});setDoc('')}}><Plus size={16}/>Agregar</button></div>{error&&<div className="error-banner">{error}</div>}</div><div className="modal-footer"><button className="button primary" onClick={async()=>{try{if(!settings.institution.trim()||!Number.isInteger(settings.insuranceThreshold)||settings.insuranceThreshold<1||settings.insuranceThreshold>90)throw Error('Revise el nombre institucional y el umbral de pólizas (1–90 días).');await mutate(s=>{s.settings=settings;audit(s,'Configuración actualizada','Preferencias institucionales de pruebas')},'Configuración guardada.');setError('')}catch(e){setError((e as Error).message)}}}><Save size={16}/>Guardar configuración</button></div></section>}
function Backups({db,mutate,toast,ask}:{db:State;mutate:Mutation;toast:(s:string)=>void;ask:Ask}){return <section className="card"><div className="card-heading"><div><h3>Respaldo institucional</h3><p>Descarga de expedientes de uso administrativo autorizado.</p></div><Database size={24}/></div><div className="modal-body"><div className="info-banner"><ShieldCheck size={22}/><span>Este respaldo local no sustituye los respaldos de Supabase ni incluye archivos de almacenamiento institucional.</span></div><div className="backup-options"><div><Download size={27}/><h3>Exportar respaldo institucional</h3><p>Descargue la información institucional que su cuenta puede consultar.</p><button className="button primary" onClick={async()=>{const blob=new Blob([JSON.stringify({format:'ctp-canas-test-backup-v1',exportedAt:new Date().toISOString(),state:db},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`CTP_Canas_respaldo_pruebas_${today()}.json`;a.click();URL.revokeObjectURL(url);await mutate(s=>audit(s,'Respaldo de pruebas descargado',`${s.students.length} expedientes`));toast('Respaldo de pruebas descargado.')}}><Download size={17}/>Descargar respaldo</button></div><div><RefreshCw size={27}/><h3>Restaurar una prueba anterior</h3><p>Seleccione un respaldo de esta aplicación. Reemplazará los datos locales actuales.</p><label className="button secondary upload-backup"><Upload size={17}/>Seleccionar respaldo<input type="file" accept=".json" onChange={async e=>{const file=e.target.files?.[0];if(!file)return;try{if(file.size>25*1024*1024)throw Error('El respaldo supera 25 MB.');const parsed=JSON.parse(await file.text());if(parsed.format!=='ctp-canas-test-backup-v1'||!Array.isArray(parsed.state?.students)||!Array.isArray(parsed.state?.enrollments)||!Array.isArray(parsed.state?.groups)||!Array.isArray(parsed.state?.years)||!Array.isArray(parsed.state?.audit)||!Array.isArray(parsed.state?.settings?.documents)||!Array.isArray(parsed.state?.settings?.specialties))throw Error('El respaldo no corresponde a esta aplicación.');const state=parsed.state as State;for(const s of state.students)if(!s.id||!s.identification||!Array.isArray(s.guardians)||!Array.isArray(s.departureContacts))throw Error('El respaldo contiene estudiantes inválidos.');for(const en of state.enrollments)if(!state.students.some(s=>s.id===en.studentId)||!Array.isArray(en.documents)||!Array.isArray(en.verified)||!en.medical)throw Error('El respaldo contiene matrículas inválidas.');const identities=state.students.map(s=>s.identification);if(new Set(identities).size!==identities.length)throw Error('El respaldo contiene identidades duplicadas.');ask({title:'Restaurar respaldo local',body:`Se reemplazarán los datos actuales con ${state.students.length} estudiantes de este respaldo. Descargue primero el respaldo actual si desea conservarlo.`,action:()=>mutate(s=>{const rev=s.revision;Object.assign(s,state,{revision:rev,transferEvents:ensureTransferHistory(state),reportArtwork:state.reportArtwork});audit(s,'Respaldo local restaurado',file.name)},'Respaldo restaurado.')})}catch(err){toast((err as Error).message)}e.target.value=''}}/></label></div></div></div></section>}
